// generated by tools/maps/itemspots.py - item spawners (SceneEditor `random-spot-N` + item markers; legacy random-* stacks), per map-list index (daemon MAPS / ext MF_MAPS)
// y = the editor position; the ext drops the pickup on the surface under it. c[k] = a candidate: game item id, offset (spot-local, rotated by q), rotation, weight.
#define ISP_MAXC 40
typedef struct {
    const char *item;
    float off[3];
    float q[4];
    int w;
} IspCandT;
// dy = visible surface - collision under the spot (added to the ray hit), sh = shared (per-player copy), fill = % (0 = ISP_FILL_PCT), resp = s (0 = ISP_RESPAWN_S)
typedef struct {
    float p[3];
    float q[4];
    int n;
    IspCandT c[ISP_MAXC];
    float dy;
    int sh, fill, resp;
} IspSpotT;
